package org.l2start.economy.market.model;

import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

import javax.xml.parsers.DocumentBuilderFactory;

import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

/** The market item catalogue (data/market-items.xml, generated by tools/gen-market-items.py). Immutable. */
public final class MarketItems {
    private final Map<Integer, MarketItem> byId;

    public MarketItems(Collection<MarketItem> items) {
        final Map<Integer, MarketItem> m = new LinkedHashMap<>();
        for (MarketItem i : items) {
            m.put(i.id(), i);
        }
        byId = Collections.unmodifiableMap(m);
    }

    public static MarketItems load(Path file) throws Exception {
        try (InputStream in = Files.newInputStream(file)) {
            return parse(in);
        }
    }

    public static MarketItems parse(InputStream in) throws Exception {
        final DocumentBuilderFactory f = DocumentBuilderFactory.newInstance();
        f.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        final NodeList nodes = f.newDocumentBuilder().parse(in).getElementsByTagName("item");
        final java.util.List<MarketItem> items = new java.util.ArrayList<>(nodes.getLength());
        for (int k = 0; k < nodes.getLength(); k++) {
            final Element e = (Element) nodes.item(k);
            items.add(new MarketItem(Integer.parseInt(e.getAttribute("id")), e.getAttribute("name"), e.getAttribute("kind"), MarketItem.Grade.of(e.getAttribute("grade")),
                Long.parseLong(e.getAttribute("price")), Boolean.parseBoolean(e.getAttribute("stackable")), Boolean.parseBoolean(e.getAttribute("npc")),
                Math.max(1, Math.min(5, Integer.parseInt(e.getAttribute("stage"))))));
        }
        return new MarketItems(items);
    }

    public MarketItem get(int id) {
        return byId.get(id);
    }

    public boolean contains(int id) {
        return byId.containsKey(id);
    }

    public int size() {
        return byId.size();
    }

    public Collection<MarketItem> all() {
        return byId.values();
    }
}
